import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        long minRem = 1L << 32;
        long bestNum = 1L << 32;
        long bestDen = 1L << 32;

        Scanner sc = new Scanner(System.in);
        long x = sc.nextLong();
        long y = sc.nextLong();
        long n = sc.nextLong();

        for (long denom = 1; denom <= n; ++denom) {
            long numerator = Math.max(x * denom / y - 10, 0);
            for (int delta = 0; delta < 20; ++delta) {
                long diff = Math.abs(x * denom - (numerator + delta) * y);
                if (minRem * denom > diff * bestDen) {
                    minRem = diff;
                    bestNum = numerator + delta;
                    bestDen = denom;
                } else if (minRem * denom == diff * bestDen) {
                    if (bestDen > denom || (bestDen == denom && bestNum > numerator + delta)) {
                        minRem = diff;
                        bestNum = numerator + delta;
                        bestDen = denom;
                    }
                }
            }
        }
        System.out.println(bestNum + "/" + bestDen);
        sc.close();
    }
}
